package com.bank.queue;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class QueueMethodsTest {

    @Test
    void remove_throwsOnEmpty() {
        Queue<String> queue = new LinkedList<>();
        assertThatThrownBy(queue::remove).isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void poll_returnsNullOnEmpty() {
        Queue<String> queue = new LinkedList<>();
        assertThat(queue.poll()).isNull();  // no exception!
    }

    @Test
    void element_throwsOnEmpty() {
        Queue<String> queue = new LinkedList<>();
        assertThatThrownBy(queue::element).isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void peek_returnsNullOnEmpty() {
        Queue<String> queue = new LinkedList<>();
        assertThat(queue.peek()).isNull();  // no exception!
    }

    @Test
    void add_throwsWhenFull() {
        Queue<String> bounded = new ArrayBlockingQueue<>(1);
        bounded.add("A");
        assertThatThrownBy(() -> bounded.add("B"))
            .isInstanceOf(IllegalStateException.class);
    }

    @Test
    void offer_returnsFalseWhenFull() {
        Queue<String> bounded = new ArrayBlockingQueue<>(1);
        assertThat(bounded.offer("A")).isTrue();
        assertThat(bounded.offer("B")).isFalse();  // full, no exception!
    }

    @Test
    void normalUsage_offerAndPoll() {
        Queue<String> queue = new LinkedList<>();
        queue.offer("TXN-001");
        queue.offer("TXN-002");
        assertThat(queue.poll()).isEqualTo("TXN-001");  // FIFO!
        assertThat(queue.poll()).isEqualTo("TXN-002");
        assertThat(queue.poll()).isNull();  // empty → null
    }
}
